package com.ruoyi.paismart.application.intelligence;
import com.ruoyi.paismart.infrastructure.intelligence.*;
import java.util.*;
import java.util.function.Consumer;
import java.util.concurrent.CancellationException;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class ModelGatewayBoundaryTest {
    ModelGateway gateway;ControlledHttp http;ModelCallService calls;ProviderService.Provider provider;ModelCallService.Call call;
    ProviderService providers;IntelligenceSettings settings;
    @BeforeEach void prepare(){providers=mock(ProviderService.class);http=mock(ControlledHttp.class);settings=mock(IntelligenceSettings.class);when(settings.number(anyString(),anyInt())).thenAnswer(i->i.getArgument(1));when(settings.number("chat.max-output-tokens",4096)).thenReturn(100);calls=mock(ModelCallService.class);call=new ModelCallService.Call("call","STARTED","reservation",null);when(calls.begin(anyLong(),anyString(),eq("LLM"),anyMap(),anyLong())).thenReturn(call);provider=new ProviderService.Provider("provider","LLM","Test","https://provider.invalid/v1","model",0,"ai.paismart.test",true,true,1,Map.of("providerCode","test"));when(providers.secret(provider)).thenReturn("test-only");when(providers.snapshot(provider)).thenReturn(Map.of("id","provider"));gateway=new ModelGateway(providers,http,settings,calls);}
    @SuppressWarnings("unchecked") void failure(RuntimeException failure,boolean usage){doAnswer(invocation->{Consumer<Map<String,Object>> data=invocation.getArgument(3);data.accept(Map.of("choices",List.of(Map.of("delta",Map.of("content","已接收内容")))));if(usage)data.accept(Map.of("usage",Map.of("total_tokens",8)));throw failure;}).when(http).sse(anyString(),anyString(),any(),any(),any());}
    @Test void partialUnknownNetworkFailureRetainsUncertainFrozenCall(){failure(new IllegalStateException("连接提前关闭"),false);StringBuilder partial=new StringBuilder();assertThrows(IllegalStateException.class,()->gateway.stream(1,"request",List.of(Map.of("role","user","content","问题")),partial::append,()->false,provider));assertEquals("已接收内容",partial.toString());verify(calls).uncertain(eq(call),anyString(),eq(Map.of("content","已接收内容")));verify(calls,never()).complete(any(),anyMap(),anyLong(),anyBoolean(),anyBoolean());}
    @Test void explicitUserStopWithoutSupplierUsageRetainsUncertainPartialCall(){failure(new CancellationException(),false);assertThrows(CancellationException.class,()->gateway.stream(1,"request",List.of(Map.of("role","user","content","问题")),part->{},()->false,provider));verify(calls).uncertain(eq(call),anyString(),eq(Map.of("content","已接收内容")));verify(calls,never()).complete(any(),any(),anyLong(),anyBoolean(),anyBoolean());}
    @Test void receivedSupplierUsageIsSettledEvenWhenTheStreamThenFails(){failure(new IllegalStateException("断开"),true);assertThrows(IllegalStateException.class,()->gateway.stream(1,"request",List.of(Map.of("role","user","content","问题")),part->{},()->false,provider));verify(calls).complete(eq(call),anyMap(),eq(8L),eq(false),eq(true));}
    List<Map<String,Object>> messages(){return List.of(Map.of("role","user","content","查订单端口"));}
    List<Map<String,Object>> schemas(){return List.of(Map.of("type","function","function",Map.of("name","search_knowledge","description","按实体查知识","parameters",Map.of("type","object","properties",Map.of("query",Map.of("type","string")),"required",List.of("query")))));}
    Map<String,Object> chunk(Map<String,Object> delta){return Map.of("choices",List.of(Map.of("delta",delta)));}
    Map<String,Object> fragment(int index,String id,String name,String arguments){Map<String,Object> call=new LinkedHashMap<>();call.put("index",index);if(id!=null)call.put("id",id);call.put("function",Map.of("name",name,"arguments",arguments));return call;}
    @Test void actualSseFragmentsMergeArgumentsByIndexAndEmitEachVisibleDeltaImmediately(){
        List<String> visible=new ArrayList<>();
        doAnswer(i->{Consumer<Map<String,Object>> output=i.getArgument(3);Map<?,?> body=i.getArgument(2);assertEquals(2000,body.get("max_tokens"));assertEquals(true,body.get("stream"));
            output.accept(chunk(Map.of("content","正在","reasoning_content","内部资料","tool_calls",List.of(fragment(1,"two","knowledge_","{"),fragment(0,"one","search_","{\"query\":\"订单")))));assertEquals(List.of("正在"),visible);
            output.accept(chunk(Map.of("content","查询。","tool_calls",List.of(fragment(0,null,"knowledge","端口\"}"),fragment(1,null,"stats","}")))));assertEquals(List.of("正在","查询。"),visible);
            output.accept(Map.of("usage",Map.of("prompt_tokens",123,"completion_tokens",7)));return null;
        }).when(http).sse(anyString(),anyString(),any(),any(),any());
        var answer=gateway.streamTurn(1,"request",messages(),schemas(),visible::add,()->false,provider);assertEquals("正在查询。",answer.get("content"));assertEquals("内部资料",answer.get("reasoning_content"));var tools=(List<?>)answer.get("tool_calls");var first=(Map<?,?>)tools.get(0);var second=(Map<?,?>)tools.get(1);assertEquals("one",first.get("id"));assertEquals("search_knowledge",((Map<?,?>)first.get("function")).get("name"));assertEquals("订单端口",com.ruoyi.paismart.infrastructure.Jsons.map(((Map<?,?>)first.get("function")).get("arguments").toString()).get("query"));assertEquals("knowledge_stats",((Map<?,?>)second.get("function")).get("name"));verify(calls).complete(eq(call),eq(answer),eq(130L),eq(false),eq(false));
    }
    @Test void stoppedTurnWithUnknownUsageKeepsAllReceivedArgumentsForManualReconciliation(){
        doAnswer(i->{Consumer<Map<String,Object>> output=i.getArgument(3);output.accept(chunk(Map.of("content","已收到","tool_calls",List.of(fragment(0,"tool","search_knowledge","{\"query\":\"待完成")))));throw new CancellationException();}).when(http).sse(anyString(),anyString(),any(),any(),any());
        assertThrows(CancellationException.class,()->gateway.streamTurn(1,"request",messages(),schemas(),p->{},()->false,provider));var partial=org.mockito.ArgumentCaptor.forClass(Object.class);verify(calls).uncertain(eq(call),anyString(),partial.capture());assertEquals("已收到",((Map<?,?>)partial.getValue()).get("content"));assertTrue(partial.getValue().toString().contains("待完成"));verify(calls,never()).complete(any(),any(),anyLong(),anyBoolean(),anyBoolean());
    }
    @Test void knownUsageOnStopSettlesExactlyOnceAndStopsInsteadOfFreezing(){
        doAnswer(i->{Consumer<Map<String,Object>> output=i.getArgument(3);output.accept(chunk(Map.of("content","一半")));output.accept(Map.of("usage",Map.of("total_tokens",5)));throw new CancellationException();}).when(http).sse(anyString(),anyString(),any(),any(),any());
        assertThrows(CancellationException.class,()->gateway.streamTurn(1,"request",messages(),schemas(),p->{},()->false,provider));verify(calls,times(1)).complete(eq(call),anyMap(),eq(5L),eq(false),eq(true));verify(calls,never()).uncertain(any(),anyString(),any());
    }
    @Test void missingUsageIncludesToolsSchemaAndGeneratedArgumentsInFallbackBudget(){
        doAnswer(i->{Consumer<Map<String,Object>> output=i.getArgument(3);output.accept(chunk(Map.of("tool_calls",List.of(fragment(0,"tool","search_knowledge","{\"query\":\""+"实体".repeat(100)+"\"}")))));return null;}).when(http).sse(anyString(),anyString(),any(),any(),any());
        var answer=gateway.streamTurn(1,"request",messages(),schemas(),p->{},()->false,provider);var reserved=org.mockito.ArgumentCaptor.forClass(Long.class);var settled=org.mockito.ArgumentCaptor.forClass(Long.class);verify(calls).begin(eq(1L),eq("request"),eq("LLM"),anyMap(),reserved.capture());verify(calls).complete(eq(call),eq(answer),settled.capture(),eq(true),eq(false));assertTrue(reserved.getValue()>2000+ModelGateway.estimate(messages().toString()));assertTrue(settled.getValue()>100);assertTrue(settled.getValue()>ModelGateway.estimateInput(messages(),schemas()));
    }
    @Test void invalidUsageCannotMakeANonemptyBillableResponseFree(){
        doAnswer(i->{Consumer<Map<String,Object>> output=i.getArgument(3);output.accept(chunk(Map.of("content","正常回答")));output.accept(Map.of("usage",Map.of("total_tokens",-1,"prompt_tokens",1.5,"completion_tokens",4)));return null;}).when(http).sse(anyString(),anyString(),any(),any(),any());
        gateway.streamTurn(1,"request",messages(),schemas(),p->{},()->false,provider);verify(calls).complete(eq(call),anyMap(),longThat(n->n>0),eq(true),eq(false));
    }
    @Test void changedToolIdentityOrOversizedArgumentsCannotExecuteAnInventedTool(){
        doAnswer(i->{Consumer<Map<String,Object>> output=i.getArgument(3);output.accept(chunk(Map.of("tool_calls",List.of(fragment(0,"first","search_","{")))));output.accept(chunk(Map.of("tool_calls",List.of(fragment(0,"different","knowledge","}")))));return null;}).when(http).sse(anyString(),anyString(),any(),any(),any());assertThrows(IllegalStateException.class,()->gateway.streamTurn(1,"request",messages(),schemas(),p->{},()->false,provider));verify(calls).uncertain(eq(call),anyString(),anyMap());
        reset(http,calls);when(calls.begin(anyLong(),anyString(),eq("LLM"),anyMap(),anyLong())).thenReturn(call);doAnswer(i->{Consumer<Map<String,Object>> output=i.getArgument(3);output.accept(chunk(Map.of("tool_calls",List.of(fragment(0,"one","search_knowledge","x".repeat(65537))))));return null;}).when(http).sse(anyString(),anyString(),any(),any(),any());assertThrows(IllegalStateException.class,()->gateway.streamTurn(1,"request",messages(),schemas(),p->{},()->false,provider));verify(calls).uncertain(eq(call),anyString(),anyMap());
    }
    @Test void completedDurableTurnReplaysItsTextAndToolsWithoutASecondRequestOrQuotaCharge()throws Exception{
        var source=new org.h2.jdbcx.JdbcDataSource();source.setURL("jdbc:h2:mem:stream_replay_"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1");try(var c=source.getConnection()){org.springframework.jdbc.datasource.init.ScriptUtils.executeSqlScript(c,new org.springframework.core.io.ClassPathResource("db/paismart/V003__intelligence.sql"));org.springframework.jdbc.datasource.init.ScriptUtils.executeSqlScript(c,new org.springframework.core.io.ClassPathResource("db/paismart/V005__evaluation_datasets.sql"));}
        var db=new org.springframework.jdbc.core.JdbcTemplate(source);db.execute("CREATE TABLE sys_user(user_id BIGINT PRIMARY KEY,status CHAR(1),del_flag CHAR(1))");db.update("INSERT INTO sys_user VALUES(1,'0','0')");var quota=mock(com.ruoyi.paismart.application.billing.QuotaService.class);when(quota.reserve(anyLong(),anyString(),eq("LLM"),anyLong())).thenAnswer(i->new com.ruoyi.paismart.application.billing.QuotaService.Reservation("reservation",1,"LLM",i.getArgument(1),"BALANCE",((Number)i.getArgument(3)).longValue(),null,"RESERVED",java.time.LocalDate.now()));
        var ledger=new ModelCallService(db,new org.springframework.transaction.support.TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(source)),quota);org.springframework.test.util.ReflectionTestUtils.setField(ledger,"members",mock(com.ruoyi.paismart.application.MembershipService.class));gateway=new ModelGateway(providers,http,settings,ledger);
        doAnswer(i->{Consumer<Map<String,Object>> output=i.getArgument(3);output.accept(chunk(Map.of("content","实际一次","tool_calls",List.of(fragment(0,"one","knowledge_stats","{}")))));output.accept(Map.of("usage",Map.of("total_tokens",14)));return null;}).when(http).sse(anyString(),anyString(),any(),any(),any());
        StringBuilder first=new StringBuilder(),replayed=new StringBuilder();var paid=gateway.streamTurn(1,"replay",messages(),schemas(),first::append,()->false,provider);var replay=gateway.streamTurn(1,"replay",messages(),schemas(),replayed::append,()->false,provider);assertEquals(paid,replay);assertEquals(first.toString(),replayed.toString());assertEquals(1L,db.queryForObject("SELECT COUNT(*) FROM ps_model_call",Long.class));assertEquals("COMPLETED",db.queryForObject("SELECT status FROM ps_model_call",String.class));verify(http,times(1)).sse(anyString(),anyString(),any(),any(),any());verify(quota,times(1)).reserve(eq(1L),eq("model:replay"),eq("LLM"),anyLong());verify(quota,times(1)).settle("reservation",14);verify(quota,never()).release(anyString());
    }
}
